import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Table Triggers in AL","description":"","frontmatter":{},"headers":[],"relativePath":"tables-fields-and-business-data/table-triggers.md","filePath":"tables-fields-and-business-data/table-triggers.md"}`),a={name:`tables-fields-and-business-data/table-triggers.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="table-triggers-in-al" tabindex="-1">Table Triggers in AL <a class="header-anchor" href="#table-triggers-in-al" aria-label="Permalink to “Table Triggers in AL”">​</a></h1><p>Table triggers let you execute AL code automatically when certain events happen to a record in a table.</p><p>Think of them as <strong>hooks into the record&#39;s lifecycle</strong>. For example, when someone inserts a new Course, you might want to validate its price or automatically populate a field.</p><p>In AL, table triggers are defined inside the table object, not inside the page.</p><h2 id="the-main-table-triggers" tabindex="-1">The main table triggers <a class="header-anchor" href="#the-main-table-triggers" aria-label="Permalink to “The main table triggers”">​</a></h2><p>Here are the triggers worth learning first:</p><table tabindex="0"><thead><tr><th>Trigger</th><th>When it runs</th><th>Common use</th></tr></thead><tbody><tr><td><code>OnInsert</code></td><td>When a new record is inserted</td><td>Set default values or perform additional checks.</td></tr><tr><td><code>OnModify</code></td><td>When an existing record is modified</td><td>React to changes to a record.</td></tr><tr><td><code>OnDelete</code></td><td>When a record is deleted</td><td>Check whether deletion should be allowed.</td></tr><tr><td><code>OnRename</code></td><td>When a record&#39;s primary key is renamed</td><td>Handle logic related to a key change.</td></tr><tr><td><code>OnValidate</code></td><td>When a field is validated</td><td>Check a field&#39;s value or update related fields.</td></tr><tr><td><code>OnInit</code></td><td>When a new record is initialized</td><td>Set initial values for a record.</td></tr><tr><td><code>OnInsert</code> and <code>OnModify</code></td><td>These are not interchangeable with <code>OnValidate</code></td><td>They handle record operations, while <code>OnValidate</code> responds to field validation.</td></tr></tbody></table><p><strong>Important distinction:</strong> <code>OnValidate</code> is a field trigger, whereas <code>OnInsert</code>, <code>OnModify</code>, <code>OnDelete</code>, and <code>OnRename</code> are table triggers. We&#39;ll see both kinds in practice.</p><h2 id="let-s-practise-using-our-course-table" tabindex="-1">Let&#39;s practise using our Course table <a class="header-anchor" href="#let-s-practise-using-our-course-table" aria-label="Permalink to “Let&#39;s practise using our Course table”">​</a></h2><p>We&#39;ll implement a simple business rule:</p><p><strong>A course cannot have a negative price.</strong></p><p>If someone enters a price below zero, Business Central should display an error and reject the value.</p><p>Open your existing <code>Course.Table.al</code> file and modify the <code>Price</code> field as follows:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(4; Price; Decimal)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Price&#39;;</span></span>
<span class="line"><span>    DataClassification = CustomerContent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    trigger OnValidate()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        if Price &lt; 0 then</span></span>
<span class="line"><span>            Error(&#39;Course price cannot be negative.&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Keep the rest of your table unchanged.</p><h3 id="understanding-the-code" tabindex="-1">Understanding the code <a class="header-anchor" href="#understanding-the-code" aria-label="Permalink to “Understanding the code”">​</a></h3><p><strong><code>trigger OnValidate()</code></strong></p><p>Runs when the field&#39;s value is validated. This can happen when a user enters a value through a page or when AL code explicitly validates the field.</p><p><strong><code>if Price &lt; 0 then</code></strong></p><p>Checks whether the price is negative.</p><p><strong><code>Error(&#39;Course price cannot be negative.&#39;);</code></strong></p><p>Displays an error and stops the operation. The invalid value won&#39;t be accepted through this validation.</p><p>Notice that we didn&#39;t need to modify our Course List page. Because the rule is defined on the <strong>table field</strong>, it applies wherever that field is validated, rather than being limited to one particular page. <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/field/devenv-onvalidate-field-trigger" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h3 id="test-it" tabindex="-1">Test it <a class="header-anchor" href="#test-it" aria-label="Permalink to “Test it”">​</a></h3><ol><li>Save your AL file.</li><li>Press <strong>F5</strong> to publish the extension.</li><li>Open <strong>Course List</strong> in Business Central.</li><li>Create a course or edit an existing course.</li><li>Enter <code>-100</code> as its price and validate the field, for example, by pressing Tab or moving to another field.</li></ol><p>You should see the error message.</p><p>Try entering <code>100</code> afterward. That value should pass our custom validation.</p><p><strong>Important:</strong> This rule runs when the field is validated. Simply assigning a value to a field in AL code doesn&#39;t necessarily execute its <code>OnValidate</code> trigger. When setting a field programmatically and wanting its validation logic to run, use <code>Record.Validate()</code>. <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-validate-method" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h2 id="what-about-the-other-triggers" tabindex="-1">What about the other triggers? <a class="header-anchor" href="#what-about-the-other-triggers" aria-label="Permalink to “What about the other triggers?”">​</a></h2><p>Now that you&#39;ve implemented one, here&#39;s how to think about the others.</p><h3 id="oninsert" tabindex="-1"><code>OnInsert()</code> <a class="header-anchor" href="#oninsert" aria-label="Permalink to “OnInsert()”">​</a></h3><p>Runs when a new record is inserted, provided the operation invokes the trigger.</p><p>For example, automatically assign a default status to a new course.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnInsert()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    // Logic to run when a course is inserted.</span></span>
<span class="line"><span>end;</span></span></code></pre></div><h3 id="onmodify" tabindex="-1"><code>OnModify()</code> <a class="header-anchor" href="#onmodify" aria-label="Permalink to “OnModify()”">​</a></h3><p>Runs when an existing record is modified, provided the operation invokes the trigger.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnModify()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    // Logic to run when a course is modified.</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Be careful about using this trigger to reject changes. Microsoft recommends avoiding logic that can prevent users from saving modifications in <code>OnModify</code>. <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/tableextension/devenv-onmodify-tableextension-trigger" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h3 id="ondelete" tabindex="-1"><code>OnDelete()</code> <a class="header-anchor" href="#ondelete" aria-label="Permalink to “OnDelete()”">​</a></h3><p>Runs when a record is about to be deleted, provided the operation invokes the trigger.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnDelete()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    // Logic to run before a course is deleted.</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>For example, you might check whether a course is referenced by other business records before allowing its deletion. <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/table/devenv-ondelete-table-trigger" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h3 id="onrename" tabindex="-1"><code>OnRename()</code> <a class="header-anchor" href="#onrename" aria-label="Permalink to “OnRename()”">​</a></h3><p>Runs when a record&#39;s primary key is renamed, provided the operation invokes the trigger.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnRename()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    // Logic related to renaming a course.</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Our Course table uses <code>&quot;Course Code&quot;</code> as its primary key, so this trigger could run when that code is changed through a rename operation. <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/tableextension/devenv-onrename-tableextension-trigger" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h2 id="complete-sample" tabindex="-1">Complete Sample <a class="header-anchor" href="#complete-sample" aria-label="Permalink to “Complete Sample”">​</a></h2><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace LearningAl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>table 50102 Course</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Course&#39;;</span></span>
<span class="line"><span>    DataClassification = CustomerContent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fields</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        field(1; &quot;Course Code&quot;; Code[20])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Course Code&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        field(2; CourseName; Text[100])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Course Name&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            trigger OnValidate()</span></span>
<span class="line"><span>            begin</span></span>
<span class="line"><span>                if CourseName = &#39;&#39; then</span></span>
<span class="line"><span>                    Error(&#39;Course name cannot be empty&#39;);</span></span>
<span class="line"><span>            end;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        field(3; CourseDescription; Text[300])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Course Description&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            trigger OnValidate()</span></span>
<span class="line"><span>            begin</span></span>
<span class="line"><span>                if CourseDescription = &#39;&#39; then</span></span>
<span class="line"><span>                    Error(&#39;Course description cannot be empty&#39;);</span></span>
<span class="line"><span>            end;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        field(4; Price; Decimal)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Price&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            trigger OnValidate()</span></span>
<span class="line"><span>            begin</span></span>
<span class="line"><span>                if Price &lt;= 0 then</span></span>
<span class="line"><span>                    Error(&#39;Course price cannot be negative&#39;);</span></span>
<span class="line"><span>            end;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    keys</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        key(PK; &quot;Course Code&quot;)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Clustered = true;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    trigger OnInsert()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;Record inserted successfully&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    trigger OnModify()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;Record updated successfully&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    trigger OnDelete()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;Record deleted successfully&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="one-important-detail-triggers-aren-t-guaranteed-to-run-for-every-al-operation" tabindex="-1">One important detail: triggers aren&#39;t guaranteed to run for every AL operation <a class="header-anchor" href="#one-important-detail-triggers-aren-t-guaranteed-to-run-for-every-al-operation" aria-label="Permalink to “One important detail: triggers aren&#39;t guaranteed to run for every AL operation”">​</a></h2><p>When a user edits a record through the Business Central interface, the system invokes the relevant triggers as part of the normal operation.</p><p>However, when you manipulate records directly through AL code, the trigger behavior can depend on the method and its arguments.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CourseRec.Insert(true);</span></span></code></pre></div><p>The <code>true</code> argument requests execution of the table&#39;s <code>OnInsert</code> trigger.</p><p>Similarly:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CourseRec.Modify(true);</span></span></code></pre></div><p>The <code>true</code> argument requests execution of the table&#39;s <code>OnModify</code> trigger.</p><p>This distinction matters when writing business logic because you shouldn&#39;t assume that every database operation automatically executes every relevant trigger. <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/tableextension/devenv-oninsert-tableextension-trigger" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h2 id="resources-for-further-reading" tabindex="-1">Resources for further reading <a class="header-anchor" href="#resources-for-further-reading" aria-label="Permalink to “Resources for further reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/it-it/dynamics365/business-central/dev-itpro/developer/triggers-auto/devenv-triggers" target="_blank" rel="noreferrer">Table triggers overview — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/field/devenv-onvalidate-field-trigger" target="_blank" rel="noreferrer">OnValidate field trigger — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-validate-method" target="_blank" rel="noreferrer">Record.Validate method — Microsoft Learn</a></li></ul><h3 id="your-takeaway" tabindex="-1">Your takeaway <a class="header-anchor" href="#your-takeaway" aria-label="Permalink to “Your takeaway”">​</a></h3><p>For now, remember three things:</p><ol><li><strong><code>OnValidate</code></strong> — validate field values and enforce field-level business rules.</li><li><strong><code>OnInsert</code>, <code>OnModify</code>, <code>OnDelete</code>, and <code>OnRename</code></strong> — respond to record lifecycle operations.</li><li><strong>Triggers are part of business logic</strong>, so put rules at the appropriate level rather than implementing them only on one page.</li></ol>`,63)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};